private _attachVideoHover(
  li: HTMLLIElement,
  videoUrl: string,
  figure: HTMLElement,
): void {
  const video = document.createElement("video");
  video.muted = true;
  video.loop = true;
  video.playsInline = true;
  video.preload = "none";
  figure.append(video);

  let isHovered = false;
  let playPromise: Promise<void> | null = null;

  const show = (): void => {
    if (isHovered) figure.classList.add("is-video-active");
  };

  const onEnter = (): void => {
    isHovered = true;
    if (!video.src) {
      video.src = videoUrl;
      video.load();
    }
    playPromise = video.play().catch(() => undefined);
    if (video.readyState >= 3) {
      show();
    } else {
      video.addEventListener("canplay", show, { once: true });
    }
  };

  const doPause = (): void => {
    video.pause();
    video.currentTime = 0;
  };

  const onLeave = (): void => {
    isHovered = false;
    video.removeEventListener("canplay", show);
    figure.classList.remove("is-video-active");
    if (playPromise !== null) {
      void playPromise.then(doPause);
      playPromise = null;
    } else {
      doPause();
    }
  };

  li.addEventListener("pointerenter", onEnter);
  li.addEventListener("pointerleave", onLeave);

  this._videoHoverCleanups.push(() => {
    isHovered = false;
    video.removeEventListener("canplay", show);
    if (playPromise !== null) {
      void playPromise.then(doPause);
      playPromise = null;
    } else {
      doPause();
    }
    li.removeEventListener("pointerenter", onEnter);
    li.removeEventListener("pointerleave", onLeave);
  });
}

