&__img {
  @include img-auto-cover(62.5%);

  img,
  video {
    @include img-cover;
    transition:
      transform var(--transition-default),
      opacity 0.35s ease;
  }

  video {
    @include pos-full();
    opacity: 0;
    pointer-events: none;
  }

  &.is-video-active {
    img {
      opacity: 0;
    }
    video {
      opacity: 1;
    }
  }
}

&__img-wrap {
  position: relative;
  padding: var(--gutter-xs);

